mapper.update:
update survey_consigner_department
set consignor_org_id = #{consignorOrgId,jdbcType=BIGINT},
  consignor_department_id = #{consignorDepartmentId,jdbcType=BIGINT},
  consigner_user_id = #{consignerUserId,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select
a.*
,d.name as consignorDepartmentName
from survey_consigner_department a
left join survey_consignor_department d on a.consignor_department_id = d.id
where 1 = 1

  and a.consignor_org_id = #{consignorOrgId,jdbcType=BIGINT}


  and a.consignor_department_id = #{consignorDepartmentId,jdbcType=BIGINT}


  and a.consigner_user_id = #{consignerUserId,jdbcType=BIGINT}
